// Monthly broker-rates sync: reads the real, committed seed/broker-rates.json
// (regenerated by scripts/export_broker_rates.py from
// pipeline.trade_cost_engine.BROKER_RATES) and upserts broker_catalog. Run
// with `npx tsx scripts/sync-broker-rates.ts` against a real DATABASE_URL.
// See the plan's "Broker fee/CTA data" section: this is the only writer of
// broker_catalog, and it never talks to the Python pipeline at runtime.
import { getDb } from "../lib/db";
import { brokerCatalog } from "../lib/schema";
import brokerRates from "../seed/broker-rates.json";

type BrokerRateEntry = {
  id: string;
  brand: string;
  tagline: string | null;
  delivery_flat: number;
  delivery_pct: number;
  intraday_flat: number;
  intraday_pct: number;
  dp_charge: number;
  demat_amc: number | null;
  account_open: number | null;
  cta_url: string;
  partner_badge: string | null;
  cap_verified_asof: string | null;
  fee_schedule_complete: boolean;
};

async function main() {
  const rows = brokerRates as BrokerRateEntry[];
  if (rows.length === 0) {
    throw new Error("broker-rates.json has zero entries; refusing to upsert an empty broker_catalog.");
  }

  const db = getDb();
  const syncedAt = new Date();

  for (const b of rows) {
    await db
      .insert(brokerCatalog)
      .values({
        id: b.id,
        brand: b.brand,
        tagline: b.tagline,
        deliveryFlat: String(b.delivery_flat),
        deliveryPct: String(b.delivery_pct),
        intradayFlat: String(b.intraday_flat),
        intradayPct: String(b.intraday_pct),
        dpCharge: String(b.dp_charge),
        dematAmc: b.demat_amc == null ? null : String(b.demat_amc),
        accountOpen: b.account_open == null ? null : String(b.account_open),
        ctaUrl: b.cta_url,
        partnerBadge: b.partner_badge,
        capVerifiedAsof: b.cap_verified_asof,
        feeScheduleComplete: b.fee_schedule_complete,
        syncedAt,
      })
      .onConflictDoUpdate({
        target: brokerCatalog.id,
        set: {
          brand: b.brand,
          tagline: b.tagline,
          deliveryFlat: String(b.delivery_flat),
          deliveryPct: String(b.delivery_pct),
          intradayFlat: String(b.intraday_flat),
          intradayPct: String(b.intraday_pct),
          dpCharge: String(b.dp_charge),
          dematAmc: b.demat_amc == null ? null : String(b.demat_amc),
          accountOpen: b.account_open == null ? null : String(b.account_open),
          ctaUrl: b.cta_url,
          partnerBadge: b.partner_badge,
          capVerifiedAsof: b.cap_verified_asof,
          feeScheduleComplete: b.fee_schedule_complete,
          syncedAt,
        },
      });
  }

  console.log(`Synced ${rows.length} brokers into broker_catalog.`);
  process.exit(0);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
